/** Every event name the runtime emits. */
export type VarionEventName =
    | "anyResourceError"
    | "anyResourceStart"
    | "anyResourceStop"
    | "baseObjectCreate"
    | "baseObjectRemove"
    | "changedVehicleSeat"
    | "connection:complete"
    | "connection:queue"
    | "connection:state"
    | "connectionComplete"
    | "consoleCommand"
    | "disconnect"
    | "discord:activityCleared"
    | "discord:activityUpdate"
    | "discord:ready"
    | "enteredVehicle"
    | "entityEnterColshape"
    | "entityHitEntity"
    | "entityLeaveColshape"
    | "entityStreamIn"
    | "entityStreamOut"
    | "everyTick"
    | "gameEntityCreate"
    | "gameEntityDestroy"
    | "gamepadButtonDown"
    | "gamepadButtonUp"
    | "gamepadConnected"
    | "gamepadDisconnected"
    | "globalMetaChange"
    | "globalSyncedMetaChange"
    | "headshotBase64"
    | "incomingDamage"
    | "keydown"
    | "keyup"
    | "leftVehicle"
    | "localEntityFailed"
    | "localMetaChange"
    | "localStorageError"
    | "locale:change"
    | "metaChange"
    | "netOwnerChange"
    | "playerAnimationChange"
    | "playerBulletHit"
    | "playerDeath"
    | "playerDimensionChange"
    | "playerEnterCheckpoint"
    | "playerEnterColShape"
    | "playerExitCheckpoint"
    | "playerExitColShape"
    | "playerInteriorChange"
    | "playerSpawn"
    | "playerStartTalking"
    | "playerStopTalking"
    | "playerWeaponChange"
    | "playerWeaponShoot"
    | "removeEntity"
    | "resourceError"
    | "resourceStart"
    | "resourceStop"
    | "rml:hide"
    | "rml:show"
    | "spawn:success"
    | "spawned"
    | "startEnteringVehicle"
    | "startLeavingVehicle"
    | "stream:mounted"
    | "streamSyncedMetaChange"
    | "syncedMetaChange"
    | "varion:ready"
    | "virtualEntityPositionChange"
    | "virtualEntityStreamIn"
    | "virtualEntityStreamOut"
    | "voice:channelChange"
    | "voice:channelCreate"
    | "voice:channelDestroy"
    | "voice:playerStartTalking"
    | "voice:playerStopTalking"
    | "voice:pushToTalk"
    | "voiceConnection"
    | "weaponDamage"
    | "webViewDestroyed"
    | "windowFocusChange"
    | "windowResolutionChange"
    | "worldObjectPositionChange"
    | "worldObjectStreamIn"
    | "worldObjectStreamOut"
    | (string & {});

/** Handler parameters of the documented events. */
export interface VarionEvents {
    /** Virtual key code (113 = F2). */
    keydown(keyCode: number): void;
    /** Virtual key code (113 = F2). */
    keyup(keyCode: number): void;
    /** Delivered to the resource being started, with its name. */
    resourceStart(resourceName: string): void;
    /** Delivered to the resource being stopped, with its name. */
    resourceStop(resourceName: string): void;
}

